mapper.update:
update borrow_record
due_date = #{dueDate}, renew_count = #{renewCount}, return_time = #{returnTime}, status = #{status}, update_time = #{updateTime},
where id = #{id}

mapper.select:

where br.user_id = #{userId}
  and br.status = '0'
  and br.due_date <= #{dueDate}
  and br.due_date >= now()
order by br.due_date asc

select b.book_name as bookName, count(br.id) as borrowCount from borrow_record br left join book b on br.book_id = b.id where 1=1
and br.borrow_time >= date_sub(now(), interval #{days} day)
group by b.id, b.book_name order by borrowCount desc limit #{limit}

select COALESCE(u.nick_name, u.user_name) as readerName, count(br.id) as borrowCount from borrow_record br left join sys_user u on br.user_id = u.user_id where 1=1
and br.borrow_time >= date_sub(now(), interval #{days} day)
group by br.user_id, u.nick_name, u.user_name order by borrowCount desc limit #{limit}
